      SUBROUTINE DIFFUN(N,T,Y,YDOT)
 
      IMPLICIT NONE
 
      INTEGER G,H
      PARAMETER (G=1000)
      PARAMETER (H=10000)
 
      INTEGER N
 
      DOUBLE PRECISION F,D,T,K(H)
      DOUBLE PRECISION X(1),TOTAL(1)
      DOUBLE PRECISION Y(N),YDOT(N)
      DOUBLE PRECISION GTOT,LAYERS,COV,DENSITES
      DOUBLE PRECISION HLOSS,NMONO
 
      COMMON/BLK1/ K,X,TOTAL,HLOSS,DENSITES,NMONO
 
C Total electron abundance
 
      X(1)=0.0
     * +Y(1)+Y(2)+Y(3)+Y(4)+Y(5)+Y(6)+Y(7)+Y(8)+Y(9)+Y(10)+Y(11)+Y(16)+Y
     * (17)+Y(18)+Y(19)+Y(20)+Y(21)+Y(22)+Y(23)+Y(24)+Y(25)+Y(26)+Y(27)+
