      CALL ODES14(N,T,Y,YDOT)
      CALL ODES15(N,T,Y,YDOT)
      CALL ODES16(N,T,Y,YDOT)
      CALL ODES17(N,T,Y,YDOT)
      CALL ODES18(N,T,Y,YDOT)
      CALL ODES19(N,T,Y,YDOT)
      CALL ODES20(N,T,Y,YDOT)
      CALL ODES21(N,T,Y,YDOT)
      CALL ODES22(N,T,Y,YDOT)
      CALL ODES23(N,T,Y,YDOT)
      CALL ODES24(N,T,Y,YDOT)
      CALL ODES25(N,T,Y,YDOT)
      CALL ODES26(N,T,Y,YDOT)
      CALL ODES27(N,T,Y,YDOT)
 
      RETURN
      END
 
      SUBROUTINE ODES1(N,T,Y,YDOT)
 
      IMPLICIT NONE
 
      INTEGER G,H
      PARAMETER (G=1000)
      PARAMETER (H=10000)
 
      INTEGER N
 
      DOUBLE PRECISION F,D,T,K(H)
      DOUBLE PRECISION X(1),TOTAL(1)
      DOUBLE PRECISION Y(N),YDOT(N)
      DOUBLE PRECISION GTOT,LAYERS,COV,DENSITES
      DOUBLE PRECISION HLOSS,NMONO
 
      COMMON/BLK1/ K,X,TOTAL,HLOSS,DENSITES,NMONO
 
 
C Total grain mantle abundance
 
      GTOT=0.0
     * +Y(12)+Y(13)+Y(14)+Y(15)+Y(42)+Y(43)+Y(44)+Y(45)+Y(46)+Y(47)+Y(48
     * )+Y(49)+Y(50)+Y(51)+Y(52)+Y(53)+Y(54)+Y(55)+Y(56)+Y(57)+Y(58)+Y(5
     * 9)+Y(60)+Y(61)+Y(62)+Y(63)+Y(73)+Y(74)+Y(75)+Y(76)+Y(77)+Y(78)+Y(
     * 79)+Y(80)+Y(81)+Y(82)+Y(83)+Y(84)+Y(85)+Y(86)+Y(87)+Y(107)+Y(108)
     * +Y(109)+Y(110)+Y(111)+Y(112)+Y(113)+Y(114)+Y(115)+Y(116)+Y(117)+Y
     * (118)+Y(119)+Y(130)+Y(131)+Y(132)+Y(133)+Y(134)+Y(135)+Y(136)+Y(1
     * 37)+Y(158)+Y(159)+Y(160)+Y(161)+Y(162)+Y(163)+Y(164)+Y(165)+Y(166
     * )+Y(167)+Y(168)+Y(186)+Y(187)+Y(188)+Y(189)+Y(190)+Y(191)+Y(192)+
     * Y(193)+Y(194)+Y(215)+Y(216)+Y(217)+Y(218)+Y(219)+Y(220)+Y(221)+Y(
     * 222)+Y(223)+Y(224)+Y(225)+Y(226)+Y(227)+Y(228)+Y(239)+Y(240)+Y(24
     * 1)+Y(242)+Y(243)+Y(244)+Y(245)+Y(246)+Y(265)+Y(266)+Y(267)+Y(268)
     * +Y(269)+Y(283)+Y(284)+Y(285)+Y(286)+Y(301)+Y(302)+Y(303)+Y(304)+Y
     * (305)+Y(306)+Y(307)+Y(315)+Y(316)+Y(317)+Y(325)+Y(326)+Y(332)+Y(3
     * 33)+Y(334)+Y(335)+Y(347)+Y(348)+Y(349)+Y(373)+Y(383)+Y(384)+Y(386
     * )+Y(387)+Y(388)+Y(392)+Y(403)+Y(404)+Y(405)+Y(406)+Y(410)+Y(415)+
     * Y(416)+Y(417)+Y(423)+Y(424)+Y(425)+Y(432)+Y(433)+Y(434)+Y(435)+Y(
     * 443)+Y(444)+Y(445)+Y(452)+Y(456)+Y(457)+Y(458)+Y(462)+Y(466)+Y(48
     * 7)+Y(489)+Y(498)+Y(514)+Y(537)+Y(543)+Y(547)+Y(563)+Y(566)+Y(567)
     * +Y(573)+Y(578)+Y(580)+Y(613)+Y(618)+Y(619)+Y(623)+Y(633)+Y(661)  
 
      LAYERS = GTOT/(NMONO*DENSITES)
 
      IF (LAYERS.LT.1.0) COV = LAYERS/GTOT
      IF (LAYERS.GE.1.0) COV = 1.0/GTOT 
 
      IF (GTOT.EQ.0.0) COV = 0.0
 
C CF+       
      F=0.0
     * +K(1413)*Y(654)*Y(298)                                           
      D=0.0
     * +K(906)*X(1)+K(6424)*Y(665)                                      
      YDOT(1)=F-D*Y(1)
 
C ClO+      
      F=0.0
     * +K(173)*Y(654)*Y(138)                                            
      D=0.0
     * +K(987)*X(1)+K(6633)*Y(665)                                      
      YDOT(2)=F-D*Y(2)
 
C H3C3O+    
      F=0.0
     * +K(5514)*Y(634)*Y(662)                                           
      D=0.0
     * +K(1028)*X(1)+K(6667)*Y(665)                                     
      YDOT(3)=F-D*Y(3)
 
C NCCNCH3+  
      F=0.0
     * +K(5542)*Y(635)*Y(473)                                           
      D=0.0
     * +K(1156)*X(1)+K(6770)*Y(665)                                     
      YDOT(4)=F-D*Y(4)
 
C SiF+      
      F=0.0
     * +K(3016)*Y(298)*Y(620)                                           
      D=0.0
     * +K(1250)*X(1)+K(6593)*Y(665)                                     
      YDOT(5)=F-D*Y(5)
 
C F+        
      F=0.0
     * +K(3261)*Y(658)*Y(298)                                           
      D=0.0
     * +K(458)*Y(667)+K(2441)*Y(667)+K(6348)*Y(665)                     
      YDOT(6)=F-D*Y(6)
 
C C5N+      
      F=0.0
     * +K(3413)*Y(660)*Y(455)                                           
      D=0.0
     * +K(848)*X(1)+K(2417)*Y(667)+K(6785)*Y(665)                       
      YDOT(7)=F-D*Y(7)
 
C C6H6+     
      F=0.0
     * +K(158)*Y(654)*Y(350)                                            
      D=0.0
     * +K(861)*X(1)+K(2835)*Y(668)+K(6807)*Y(665)                       
      YDOT(8)=F-D*Y(8)
 
C CH3C3N+   
      F=0.0
     * +K(2442)*Y(667)*Y(25)                                            
      D=0.0
     * +K(927)*X(1)+K(2431)*Y(667)+K(6761)*Y(665)                       
      YDOT(9)=F-D*Y(9)
 
C H2CCl+    
      F=0.0
     * +K(2084)*Y(635)*Y(353)+K(2493)*Y(638)*Y(31)                      
      D=0.0
     * +K(994)*X(1)+K(6625)*Y(665)                                      
      YDOT(10)=F-D*Y(10)
 
C HF+       
      F=0.0
     * +K(2441)*Y(667)*Y(6)                                             
      D=0.0
     * +K(1113)*X(1)+K(2455)*Y(667)+K(6349)*Y(665)                      
      YDOT(11)=F-D*Y(11)
 
C GHe       
      F=0.0
     * +K(6891)*Y(659)                                                  
      D=0.0
     * +K(7073)*COV+K(7255)*COV+K(7437)*COV                             
      YDOT(12)=F-D*Y(12)
 
C GNa       
      F=0.0
     * +K(6906)*Y(552)                                                  
      D=0.0
     * +K(7088)*COV+K(7270)*COV+K(7452)*COV                             
      YDOT(13)=F-D*Y(13)
 
C GMg       
      F=0.0
     * +K(6907)*Y(549)                                                  
      D=0.0
     * +K(7089)*COV+K(7271)*COV+K(7453)*COV                             
      YDOT(14)=F-D*Y(14)
 
C GFe       
      F=0.0
     * +K(7017)*Y(548)                                                  
      D=0.0
     * +K(7199)*COV+K(7381)*COV+K(7565)*COV                             
      YDOT(15)=F-D*Y(15)
 
C PN+       
      F=0.0
     * +K(413)*Y(647)*Y(354)                                            
      D=0.0
     * +K(250)*Y(664)+K(1212)*X(1)+K(3753)*Y(663)+K(6561)*Y(665)        
      YDOT(16)=F-D*Y(16)
 
C C2O+      
      F=0.0
     * +K(152)*Y(654)*Y(393)+K(332)*Y(647)*Y(393)+K(2270)*Y(516)*Y(599) 
      D=0.0
     * +K(786)*X(1)+K(6475)*Y(665)                                      
      YDOT(17)=F-D*Y(17)
 
C C3H2O+    
      F=0.0
     * +K(5508)*Y(636)*Y(662)                                           
      D=0.0
     * +K(797)*X(1)+K(798)*X(1)+K(6656)*Y(665)+K(6657)*Y(665)           
      YDOT(18)=F-D*Y(18)
 
C C4P+      
      F=0.0
     * +K(342)*Y(647)*Y(287)                                            
      D=0.0
     * +K(834)*X(1)+K(835)*X(1)+K(6810)*Y(665)+K(6811)*Y(665)           
      YDOT(19)=F-D*Y(19)
 
C C7N+      
      F=0.0
     * +K(3430)*Y(660)*Y(420)+K(6051)*Y(414)                            
      D=0.0
     * +K(877)*X(1)+K(2422)*Y(667)+K(6841)*Y(665)                       
      YDOT(20)=F-D*Y(20)
 
C C8H5+     
      F=0.0
     * +K(5577)*Y(616)*Y(585)                                           
      D=0.0
     * +K(888)*X(1)+K(889)*X(1)+K(6854)*Y(665)+K(6855)*Y(665)           
      YDOT(21)=F-D*Y(21)
 
C C9H5+     
      F=0.0
     * +K(5580)*Y(616)*Y(470)                                           
      D=0.0
     * +K(900)*X(1)+K(901)*X(1)+K(6866)*Y(665)+K(6867)*Y(665)           
      YDOT(22)=F-D*Y(22)
 
C C9N+      
      F=0.0
     * +K(3447)*Y(660)*Y(400)+K(6069)*Y(372)                            
      D=0.0
     * +K(902)*X(1)+K(2427)*Y(667)+K(6876)*Y(665)                       
      YDOT(23)=F-D*Y(23)
 
C CH2CHCN+  
      F=0.0
     * +K(3402)*Y(660)*Y(464)+K(6090)*Y(391)                            
      D=0.0
     * +K(913)*X(1)+K(2430)*Y(667)+K(6652)*Y(665)                       
      YDOT(24)=F-D*Y(24)
 
C H2C4N+    
      F=0.0
     * +K(1351)*Y(654)*Y(391)+K(2447)*Y(667)*Y(26)                      
      D=0.0
     * +K(989)*X(1)+K(2442)*Y(667)+K(6746)*Y(665)                       
      YDOT(25)=F-D*Y(25)
 
      RETURN
      END
 
      SUBROUTINE ODES2(N,T,Y,YDOT)
 
      IMPLICIT NONE
 
      INTEGER G,H
      PARAMETER (G=1000)
      PARAMETER (H=10000)
 
      INTEGER N
 
      DOUBLE PRECISION F,D,T,K(H)
      DOUBLE PRECISION X(1),TOTAL(1)
      DOUBLE PRECISION Y(N),YDOT(N)
      DOUBLE PRECISION GTOT,LAYERS,COV,DENSITES
      DOUBLE PRECISION HLOSS,NMONO
 
      COMMON/BLK1/ K,X,TOTAL,HLOSS,DENSITES,NMONO
 
 
C Total grain mantle abundance
 
      GTOT=0.0
     * +Y(12)+Y(13)+Y(14)+Y(15)+Y(42)+Y(43)+Y(44)+Y(45)+Y(46)+Y(47)+Y(48
     * )+Y(49)+Y(50)+Y(51)+Y(52)+Y(53)+Y(54)+Y(55)+Y(56)+Y(57)+Y(58)+Y(5
     * 9)+Y(60)+Y(61)+Y(62)+Y(63)+Y(73)+Y(74)+Y(75)+Y(76)+Y(77)+Y(78)+Y(
     * 79)+Y(80)+Y(81)+Y(82)+Y(83)+Y(84)+Y(85)+Y(86)+Y(87)+Y(107)+Y(108)
     * +Y(109)+Y(110)+Y(111)+Y(112)+Y(113)+Y(114)+Y(115)+Y(116)+Y(117)+Y
     * (118)+Y(119)+Y(130)+Y(131)+Y(132)+Y(133)+Y(134)+Y(135)+Y(136)+Y(1
     * 37)+Y(158)+Y(159)+Y(160)+Y(161)+Y(162)+Y(163)+Y(164)+Y(165)+Y(166
     * )+Y(167)+Y(168)+Y(186)+Y(187)+Y(188)+Y(189)+Y(190)+Y(191)+Y(192)+
     * Y(193)+Y(194)+Y(215)+Y(216)+Y(217)+Y(218)+Y(219)+Y(220)+Y(221)+Y(
     * 222)+Y(223)+Y(224)+Y(225)+Y(226)+Y(227)+Y(228)+Y(239)+Y(240)+Y(24
     * 1)+Y(242)+Y(243)+Y(244)+Y(245)+Y(246)+Y(265)+Y(266)+Y(267)+Y(268)
     * +Y(269)+Y(283)+Y(284)+Y(285)+Y(286)+Y(301)+Y(302)+Y(303)+Y(304)+Y
     * (305)+Y(306)+Y(307)+Y(315)+Y(316)+Y(317)+Y(325)+Y(326)+Y(332)+Y(3
     * 33)+Y(334)+Y(335)+Y(347)+Y(348)+Y(349)+Y(373)+Y(383)+Y(384)+Y(386
     * )+Y(387)+Y(388)+Y(392)+Y(403)+Y(404)+Y(405)+Y(406)+Y(410)+Y(415)+
     * Y(416)+Y(417)+Y(423)+Y(424)+Y(425)+Y(432)+Y(433)+Y(434)+Y(435)+Y(
     * 443)+Y(444)+Y(445)+Y(452)+Y(456)+Y(457)+Y(458)+Y(462)+Y(466)+Y(48
     * 7)+Y(489)+Y(498)+Y(514)+Y(537)+Y(543)+Y(547)+Y(563)+Y(566)+Y(567)
     * +Y(573)+Y(578)+Y(580)+Y(613)+Y(618)+Y(619)+Y(623)+Y(633)+Y(661)  
 
      LAYERS = GTOT/(NMONO*DENSITES)
 
      IF (LAYERS.LT.1.0) COV = LAYERS/GTOT
      IF (LAYERS.GE.1.0) COV = 1.0/GTOT 
 
      IF (GTOT.EQ.0.0) COV = 0.0
 
C HC4N+     
      F=0.0
     * +K(1542)*Y(648)*Y(379)+K(3407)*Y(660)*Y(612)                     
      D=0.0
     * +K(1074)*X(1)+K(2447)*Y(667)+K(6745)*Y(665)                      
      YDOT(26)=F-D*Y(26)
 
C HNS+      
      F=0.0
     * +K(2728)*Y(646)*Y(426)+K(2982)*Y(655)*Y(426)+K(3527)*Y(560)*Y(649
     * )                                                                
      D=0.0
     * +K(1123)*X(1)+K(6590)*Y(665)                                     
      YDOT(27)=F-D*Y(27)
 
C HSO+      
      F=0.0
     * +K(2518)*Y(586)*Y(649)+K(2743)*Y(646)*Y(602)+K(2991)*Y(655)*Y(602
     * )                                                                
      D=0.0
     * +K(1142)*X(1)+K(6626)*Y(665)                                     
      YDOT(28)=F-D*Y(28)
 
C COOCH3+   
      F=0.0
     * +K(5650)*Y(654)*Y(237)                                           
      D=0.0
     * +K(1271)*X(1)+K(1272)*X(1)+K(6695)*Y(665)+K(6696)*Y(665)         
      YDOT(29)=F-D*Y(29)
 
C HOC+      
      F=0.0
     * +K(1395)*Y(654)*Y(653)+K(2436)*Y(667)*Y(575)+K(2677)*Y(646)*Y(662
     * )                                                                
      D=0.0
     * +K(138)*Y(667)+K(1126)*X(1)+K(6391)*Y(665)                       
      YDOT(30)=F-D*Y(30)
 
C CCl+      
      F=0.0
     * +K(160)*Y(654)*Y(195)+K(1412)*Y(654)*Y(353)                      
      D=0.0
     * +K(905)*X(1)+K(2493)*Y(638)+K(3567)*Y(637)+K(6600)*Y(665)        
      YDOT(31)=F-D*Y(31)
 
C CH3CS+    
      F=0.0
     * +K(1717)*Y(630)*Y(624)+K(3825)*Y(624)*Y(524)+K(3848)*Y(565)*Y(630
     * )+K(3854)*Y(565)*Y(520)                                          
      D=0.0
     * +K(955)*X(1)+K(6689)*Y(665)                                      
      YDOT(32)=F-D*Y(32)
 
C H2CNO+    
      F=0.0
     * +K(2696)*Y(646)*Y(320)+K(2898)*Y(100)*Y(667)                     
      D=0.0
     * +K(995)*X(1)+K(996)*X(1)+K(6537)*Y(665)+K(6538)*Y(665)           
      YDOT(33)=F-D*Y(33)
 
C H2F+      
      F=0.0
     * +K(2455)*Y(667)*Y(11)+K(2706)*Y(646)*Y(298)                      
      D=0.0
     * +K(1005)*X(1)+K(1006)*X(1)+K(6350)*Y(665)+K(6351)*Y(665)         
      YDOT(34)=F-D*Y(34)
 
C H2NCO+    
      F=0.0
     * +K(2708)*Y(646)*Y(341)+K(3048)*Y(147)*Y(667)                     
      D=0.0
     * +K(1009)*X(1)+K(1010)*X(1)+K(6539)*Y(665)+K(6540)*Y(665)         
      YDOT(35)=F-D*Y(35)
 
C H2NO+     
      F=0.0
     * +K(2710)*Y(646)*Y(482)+K(3525)*Y(560)*Y(645)                     
      D=0.0
     * +K(1011)*X(1)+K(1012)*X(1)+K(6432)*Y(665)+K(6433)*Y(665)         
      YDOT(36)=F-D*Y(36)
 
C H2OCN+    
      F=0.0
     * +K(2712)*Y(646)*Y(324)+K(3052)*Y(102)*Y(667)                     
      D=0.0
     * +K(1016)*X(1)+K(1017)*X(1)+K(6546)*Y(665)+K(6547)*Y(665)         
      YDOT(37)=F-D*Y(37)
 
C HSiO2+    
      F=0.0
     * +K(2760)*Y(646)*Y(214)+K(3005)*Y(655)*Y(214)                     
      D=0.0
     * +K(1146)*X(1)+K(1147)*X(1)+K(6724)*Y(665)+K(6725)*Y(665)         
      YDOT(38)=F-D*Y(38)
 
C NH2CNH+   
